import{_ as e,a as i,b as o}from"./chunks/image-20250818054748974.ACqxcLjl.js";import{_ as p,c as t,a2 as s,o as l}from"./chunks/framework.C_CzCF4k.js";const r="/images/image-20260902093643570.webp",d="/images/image-20260902093721661.webp",c="/images/image-20260717085818401.webp",n="/images/image-20260717084644811.webp",m="/images/image-20260717084800049.webp",h="/images/image-20260717090341267.webp",g="/images/image-20260717090558300.webp",b="/images/image-20260717091254569.webp",_="/images/image-20260717091320152.webp",u="/images/image-20260717091417444.webp",f="/images/image-20260717091438590.webp",x="/images/image-20260728073428281.webp",q="/images/image-20260728073512939.webp",y="/images/%E6%95%B0%E9%80%89%E9%A1%B6%E5%B1%8F3.gif",k="/images/%E6%95%B0%E9%80%89%E9%A1%B6%E5%B1%8F1.gif",P="/images/%E6%95%B0%E9%80%89%E9%A1%B6%E5%B1%8F2.gif",z="/images/%E6%95%B0%E9%80%89%E9%A1%B6%E5%B1%8F6.gif",j=JSON.parse('{"title":"声笔飞天","description":"","frontmatter":{"title":"声笔飞天","date":"2026-7-17","comments":false,"tags":["声笔","飞天","顶功"],"typora-root-url":"..\\\\..\\\\public","typora-copy-images-to":"./..\\\\..\\\\public\\\\images"},"headers":[],"relativePath":"sbft/index.md","filePath":"docs/sbft/index.md"}'),E={name:"sbft/index.md"};function B(S,a,T,w,A,F){return l(),t("div",null,[...a[0]||(a[0]=[s('<h2 id="_1-飞天概述" tabindex="-1">1 飞天概述 <a class="header-anchor" href="#_1-飞天概述" aria-label="Permalink to &quot;1 飞天概述&quot;">​</a></h2><p>声笔飞天，简称飞天，是一款受到声笔象码的启发而在飞单基础上衍生出来的的新型延迟顶功方案，是声笔飞系的新成员。相比飞单来说，飞天的单字模式采用了42延迟顶，取消了sf型标点字词，词组借用了象码的方式来实现四码顶屏和快速笔画筛重。飞天的词组模式下，单字的输入类似飞码，而词组的输入则具有了快速笔画筛重的能力。飞天默认为使用单字模式。</p><p>由于飞码的单字编码与飞单完全相同，同时对于单字派来说，可能只关心和使用飞单，所以飞单是独立成章进行讲解的。若您是初学者，请务必先了解和掌握<a href="./../sbfd/">声笔飞单</a>，然后再回过头来继续学习飞天。</p><h2 id="_2-飞天基础" tabindex="-1">2 飞天基础 <a class="header-anchor" href="#_2-飞天基础" aria-label="Permalink to &quot;2 飞天基础&quot;">​</a></h2><h3 id="_2-1-单字输入" tabindex="-1">2.1 单字输入 <a class="header-anchor" href="#_2-1-单字输入" aria-label="Permalink to &quot;2.1 单字输入&quot;">​</a></h3><p>飞天在输入单字时，四码及之前的编码与飞单完全一样，然而有一个最大的区别，那就是需要延迟一码才顶屏，即所谓42顶，用第四码顶二简字上屏。</p><p>例如，「作为」在输入zrw时并不将「作」顶上屏而留下w，而是在继续输入o时才会顶「作」上屏而留下wo。</p><p>此外，飞天不是四码后翻页查找重码，而是直接追加笔画，直到码长为10为止，笔画不够时重复末笔。同时，会提示加一码后会出现的字。</p><p><img src="'+r+'" alt="image-20260902093643570" loading="lazy"></p><p><img src="'+d+'" alt="image-20260902093721661" loading="lazy"></p><p>还有，飞天取消了飞单里的sf型标点字（sbf型的标点字仍然支持），以便支持四码起顶的词组。还有，默认不会提示数选字，但仍然可以正常使用，在用全码输入时也会提醒。</p><p><img src="'+c+'" alt="image-20260717085818401" loading="lazy"></p><h3 id="_2-2-词组输入" tabindex="-1">2.2 词组输入 <a class="header-anchor" href="#_2-2-词组输入" aria-label="Permalink to &quot;2.2 词组输入&quot;">​</a></h3><p>飞天默认就支持飞单增强模式下的数选词，不用专门开启，但不会进行后码提示。</p><h4 id="_2-2-1-简码" tabindex="-1">2.2.1 简码 <a class="header-anchor" href="#_2-2-1-简码" aria-label="Permalink to &quot;2.2.1 简码&quot;">​</a></h4><p>飞天的简码词与飞单基本一样，包括声声词、数选词，但取消了标点词。需要注意的时，在默认情况下，并没有提示数选词，不过仍然可以照常使用，而且在输入全码后会提醒简码。</p><p><img src="'+n+'" alt="image-20260717084644811" loading="lazy"></p><h4 id="_2-2-2-全码" tabindex="-1">2.2.2 全码 <a class="header-anchor" href="#_2-2-2-全码" aria-label="Permalink to &quot;2.2.2 全码&quot;">​</a></h4><p>飞天的全码词分为共享和专用两类。</p><h5 id="_2-2-2-1-共享类" tabindex="-1">2.2.2.1 共享类 <a class="header-anchor" href="#_2-2-2-1-共享类" aria-label="Permalink to &quot;2.2.2.1 共享类&quot;">​</a></h5><p>此类编码为所有的词组共享，其格式中的前四位为<code>sxsf</code>，其中：s为声母，x为声母或笔画，f为符号笔画，可以为<code>&#39;,/;.</code>，分别表示折横撇竖捺，与<code>aeuio</code>形成对应。</p><ul><li><p>二字词：22万多个，编码格式为<code>s¹x¹s⁰f⁰b¹b¹b⁰b⁰b⁰b⁰</code>，即取首字的前两码和末字声母及末字首笔的符号形式，可再用字母笔画补充首字的前两笔和末字的前四笔，笔画不足则重复末笔。简单来说，就是在基础四码上加首字两笔再加末字四笔。</p></li><li><p>三字词：30万多个，编码格式为<code>s¹x²s⁰f⁰b¹b¹b²b²b⁰b⁰</code>，即取前三字的首码和末字首笔的符号形式，可再用字母笔画补充各字的前两笔。简单来说，就是在基础四码上加前三字各两笔画。</p></li><li><p>多字词：53万多个，编码格式为<code>s¹x²s³f⁰b¹b¹b²b²b³b³</code>，即取前三字的首码和末字首笔的符号形式，可再用字母笔画补充前三字的前两笔。简单来说，就是在基础四码上加前三字各两笔画。</p><p><img src="'+m+'" alt="image-20260717084800049" loading="lazy"></p><p>在上图中，输入<code>srg/</code>的时候，首选出现了「傻瓜」一词。首选后面跟着五个重码词虽然可用23789来选择，但更好的方法是追加笔画进行快速筛选，直到成为首选后以便顶屏省键。比如，要输入「使馆」，可补充首字的笔画，结果下所示。</p><p><img src="'+h+'" alt="image-20260717090341267" loading="lazy"></p><p>若在当页没有出现，那么可以继续补充笔画，最多可补笔画到码长为10为止。例如，「杀人鬼」可以再加「杀」的第二笔就到首选了。</p><p><img src="'+g+'" alt="image-20260717090558300" loading="lazy"></p><p>当然也可用Tab和Shift+Tab前后翻页来查找，但是效率低下，通常只在不清楚后续笔画时才使用。</p></li></ul><h5 id="_2-2-2-2-专用类" tabindex="-1">2.2.2.2 专用类 <a class="header-anchor" href="#_2-2-2-2-专用类" aria-label="Permalink to &quot;2.2.2.2 专用类&quot;">​</a></h5><p>此类编码分为两型，分别专用于四字词和多字词。此类编码可以缩短码长，但操作相对较难，用到了大写字母，通常只用于首次输入时快速去重，之后就可用<code>sxsf</code>格式更快地输入了。</p><ul><li><p>sssS型：此型为四字词专用的全动态编码，其格式为<code>s¹s²s³S⁰b¹b¹b²b²b³b³</code>，即取前三字和末的首码，但要大写第四码，可再用字母笔画补充前三字的前两笔。</p><p><img src="'+b+'" alt="image-20260717091254569" loading="lazy"></p><p><img src="'+_+'" alt="image-20260717091320152" loading="lazy"></p></li><li><p>ssSs型：此型为五字及以上的多字词专用的全动态编码，其格式与四字词一样，但需要大写第三码。</p><p><img src="'+u+'" alt="image-20260717091417444" loading="lazy"></p><p><img src="'+f+'" alt="image-20260717091438590" loading="lazy"></p></li></ul><h2 id="_4-设置选项" tabindex="-1">4 设置选项 <a class="header-anchor" href="#_4-设置选项" aria-label="Permalink to &quot;4 设置选项&quot;">​</a></h2><h3 id="_4-1-过滤强度" tabindex="-1">4.1 过滤强度 <a class="header-anchor" href="#_4-1-过滤强度" aria-label="Permalink to &quot;4.1 过滤强度&quot;">​</a></h3><p>飞天的单字模式是单字二码起顶的，有大量的常用单字仅用两三键就可以输入。为了避免低效的词组输入，可对词组进行了过滤。过滤强度可以设置的值有3、4、5或6，只对全码词起作用。</p><p>默认的过滤强度filter_strength设置为3，即不进行过滤。当设置为4时，只有码长组合为22的二字词会被过滤掉。如果过滤强度设置为5，二字词的组成字码长为22、23、32这三种组合时就会被过滤掉。如果过滤强度设置为6，码长组合为33（但不含24和42）的二字词和码长组合为222的三字词都会被过滤掉。过滤强度设得越强，就越趋向于主单，即越趋向于以单字为主来进行输入。注意，在计算码长的时候，标点字和数选字并未算成是简码，而是按四码算的。</p><h3 id="_4-2-主词模式" tabindex="-1">4.2 主词模式 <a class="header-anchor" href="#_4-2-主词模式" aria-label="Permalink to &quot;4.2 主词模式&quot;">​</a></h3><p>为了适应以词组为主导的应用场景，飞天还提供了主词模式。可以用F4或Ctrl+~临时切换到主词模式，也可修改sbft.schema.yaml文件，将词组模式设为默认模式。在词组模式下，二简字一般需要用空格上屏，词组的简码不变，而词组的全码变为以下形式。</p><ul><li>二字词：<code>s¹x¹s²x²b¹b¹b²b²b²b²</code>，即取各字的前两码，可再用字母笔画补充首字的前两笔和第二字的前四笔，笔画不足则重复末笔。</li><li>三字词：<code>s¹s²s³x³b¹b¹b²b²b³b³</code>，即取前两字的首码和第三字的前两码，可再用字母笔画补充各字的前两笔。</li><li>多字词：<code>s¹s²s³s⁰b¹b¹b²b²b³b³</code>，即取前三字的首码和末字的首码，可再用字母笔画补充前三字的前两笔。</li></ul><p>在词组模式下，不会对词组进行任何过滤，常规词组的编码空间由主单时的<code>21*26*21*5^7 = 895,781,250</code>增加到了<code>21*26*21*26*5^6 = 4,658,062,500</code>。词组的重码既可像随时用数字进行选择上屏，必要时用Tab和Shift+Tab翻页，更可通过不断追加笔画进行快速筛选。</p><h3 id="_4-3-词组分流" tabindex="-1">4.3 词组分流 <a class="header-anchor" href="#_4-3-词组分流" aria-label="Permalink to &quot;4.3 词组分流&quot;">​</a></h3><p>为了减少词组的重码，可将sbft.schema.yaml文件中translator项下的forced_selection子项设为true，以便过滤掉四字及以上的词组。</p><h2 id="_5-组合变换" tabindex="-1">5 组合变换 <a class="header-anchor" href="#_5-组合变换" aria-label="Permalink to &quot;5 组合变换&quot;">​</a></h2><h3 id="_5-1-一般组合" tabindex="-1">5.1 一般组合 <a class="header-anchor" href="#_5-1-一般组合" aria-label="Permalink to &quot;5.1 一般组合&quot;">​</a></h3><p>与飞码类似，飞天可以通过编码变换，将简字组合起来输入，从而节约用键。</p><p>(1) 一简字与一简字的组合</p><p>例如，「个人」一词，虽然可以按词组的方式用<code>grrp</code>来输入。更好的方式是当成两个一简字用<code>g_r_</code>来输入，其中下划线表示空格。然而，最好的方式则是采用编码变换，用<code>gr;</code>来输入，可以节约一次用键。</p><p>(2) 一简字与二简字的组合</p><p>例如，「一会」可以用<code>yhu;</code>代替<code>yhhu</code>来输入，虽然不能节约用键，但是输入变得确定了，而且可以将<code>yhhu</code>的首选让给「与会」，就起到了离散重码的作用。再如，「一场」可以用<code>yct;</code>代替<code>yhct</code>。</p><p>(3) 二简词与一简字的组合</p><p>二简词与一简字可以组合起来通过Tab一起上屏，从而节约一次空格键。例如，「我们的」在常规输入时，得用<code>wm + Tab + d + 空格</code>，而利用组合变换后就只需<code>wmd + Tab</code>了。</p><p>(4) 二简字与二简字的组合</p><p>例如，「回改」在飞码默认词库中是没有的，然而用户可能会误以为它是个库里有的词，于是就输入编码<code>higj</code>，但是发现只有「回锅」一个候选项。这时，如果用退格键删除后面两码，加空格上屏「回」字，再输入「改」字，代价是相当高昂的。幸好，有了组合变换的手段，加个分号就可以变为「回改」，并且也自动造好了这个词，下次就可以用词组来输入「回改」了。</p><p>如果是两个声笔字的组合，那么肯定是唯一的，不管是不是词，飞码都会给出这个唯一的首选项。比如，「大家dejo」「进大jede」等等。注意选项后的五角星，它表示是输入法给出的单字组合。</p><p><img src="'+e+'" alt="image-20250820114946980" loading="lazy"></p><p>(5) 二简字与三简字或四码字的组合</p><p>二简字与三简字可以组合起来通过分号一起上屏，虽然有时并不能节约用键，但可以避免回改。</p><p>例如，假设想用户以为「都顶」是个系统有的词组，然而输入<code>dvdy</code>后发现没有该词，同时又知道「都」是二简字、「顶」是三简字，于是就可追加「顶」的第三码<code>e</code>后，再用分号变换来上屏「都顶」。</p><p><img src="'+x+'" alt="image-20260728073428281" loading="lazy"></p><p><img src="'+q+'" alt="image-20260728073512939" loading="lazy"></p><p>再如，在输入「飞系」的时候，发现系统没有该词，而且「系」字的第三码u又没有被重码词占用，那么在输入u的时候就会将「飞」字与「系」字组合，形成「飞系」。这样，就不必用退格键来清除xx两码，用空格先上屏「飞」字，再输入「系」字了。在继续输入时，「飞系」就被顶上屏幕了，比用单字输入节约一键。顶屏的时候，并不会造词。<u>若想同时造词，那么就用分号组合上屏。</u></p><p><img src="'+i+'" alt="image-20250818054730080" loading="lazy"></p><p><img src="'+o+'" alt="image-20250818054748974" loading="lazy"></p><p>(6) 二简字与二简词的组合</p><p>二简字与二简词可以组合起来通过单引号一起上屏，从而节约一次空格键。例如，「也必须」用单引号组合变化后，用<code>yabx&#39;</code>就可以输入了，否则就需要用<code>ya_bx&#39;</code>来输入。</p><p>(7) 三个一简字的组合，可以用Shift+空格来输入，手机上可上滑空格。例如，「一个人」「就是了」「是不是」「不是不」等都可以这样输入。</p><p>(8) 二简字加两个一简字的组合，可以用Shift+空格来输入，手机上可上滑空格。例如，「有一个」「这个人」「那不是」「走下去」等都可以这样输入。</p><p>(9) 二简词加二简字的组合，可以用Tab来输入。例如，「得到先」「相信她」「一般会」等都可以这样输入。</p><p>(10) 两个一简字加一个二简字的组合，可以用Shift+Tab来输入，手机上可上滑Tab。例如，「个人这」「不是会」「去了吧」等都可以这样输入。</p><h3 id="_5-2-复杂组合" tabindex="-1">5.2 复杂组合 <a class="header-anchor" href="#_5-2-复杂组合" aria-label="Permalink to &quot;5.2 复杂组合&quot;">​</a></h3><p>当二字词中的首字不是一、二简字的时候，在输入四码及以上后若发现首字不对，可以用Ctrl+L定位到第二码后进行快改，但是操作步骤仍然太多。有没有更便捷的方法呢？有的。那就是用大写的AEUIO追加首字的第三码，若有必要还可追加它的第四码。在追加第四码时可以不再用大写。当然，在第二字也不是一、二简字时，如果需要追加第二字的编码则应该先追加，然后再追加第一字的编码。</p><p>例如，要想输入「顶屏」一词，在输入dyps后发现系统中没有。若你知道「顶」和「屏」均为三简字，那么可以追加「屏」的第三码o，然后用大写追加「顶」的第三码E，「顶屏」一词便作为组合出现在首选了。此时，空格上屏或者顶屏输入，那么是不会造词的，但若用分号进行变换上屏就会造词。新造的词在输入一次后，再输入的话一般就会变成首选。</p><p><img src="'+y+'" alt="数选顶屏3" loading="lazy"></p><h3 id="_5-3-大写巧用" tabindex="-1">5.3 大写巧用 <a class="header-anchor" href="#_5-3-大写巧用" aria-label="Permalink to &quot;5.3 大写巧用&quot;">​</a></h3><p>在后续字词的声母时，若用大写，可以进行顶屏操作，一般使用在二简字后忘记加空格的时候。</p><p>例如，在输入「有东西」时，输入了ye但忘记了加空格上屏，接着输入了dh，这时出来的是「有灯」。不管是用ESC清除后重新输入，还是用退格键修改，成本都非常高。然而，接着用大写输入「西」的首码X，「有」字就会被顶上屏幕，剩下dhx三码，再输入「西」的第二码h即可输入「东西」了。</p><h3 id="_5-4-数选顶屏" tabindex="-1">5.4 数选顶屏 <a class="header-anchor" href="#_5-4-数选顶屏" aria-label="Permalink to &quot;5.4 数选顶屏&quot;">​</a></h3><p>飞天在默认情况下就支持数选字词，在全码时会进行提示，但是不进行后码提示，所以需要记住后才能用起来。</p><p>在sxs后输入数字，会顶sx对应的二简字上屏而留下数选字。在sxsx后输入数字，会顶sx对应的二简字上屏而留下数选词。因为二简字和数选字词都是很常用的，所以用好后可以节约不少的空格。</p><p><img src="'+k+'" alt="数选顶屏1" loading="lazy"></p><p><img src="'+P+'" alt="数选顶屏2" loading="lazy"></p><h2 id="_6-盲打练习" tabindex="-1">6 盲打练习 <a class="header-anchor" href="#_6-盲打练习" aria-label="Permalink to &quot;6 盲打练习&quot;">​</a></h2><h3 id="_6-1-隐藏提示" tabindex="-1">6.1 隐藏提示 <a class="header-anchor" href="#_6-1-隐藏提示" aria-label="Permalink to &quot;6.1 隐藏提示&quot;">​</a></h3><p>为了有意识地训练盲打能力，在学习到一定阶段后，可以将提示选项设置为「隐藏」，从而关闭声笔字、声声词和数选字词的提示。</p><p>声笔字的盲打能力在飞天中有着举足轻重的作用，也是初学者要过的重要关口。关闭声笔字的提示有助于用户尽快摆脱在输入过程中不自觉地查看声笔字候选项的习惯，实现声笔字的盲打。声声词是高频的的二字词，能做到盲打时，对打字效率的提升也是相当重要的。 对于高手而言，很多数选字词也是可以盲打的。</p><h3 id="_6-2-隐藏窗口" tabindex="-1">6.2 隐藏窗口 <a class="header-anchor" href="#_6-2-隐藏窗口" aria-label="Permalink to &quot;6.2 隐藏窗口&quot;">​</a></h3><p>在小狼毫上如何把编码和候选窗口都隐藏掉，实现强制进行盲打？为此，在专门为声笔飞天盲打做了一个声笔魔飞方案，它默认隐藏候选窗口并将首选嵌入到光标插入点处。可以在有编码时通过快捷键Ctrl+J切换到魔飞，在需要查看候选时又可快速切换回飞天。</p><p><img src="'+z+'" alt="数选顶屏6" loading="lazy"></p>',81)])])}const v=p(E,[["render",B]]);export{j as __pageData,v as default};
